using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestClass]
    public sealed class FormatPhoneNumberTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void FormatsValidDigits_ReturnsParenthesizedAreaCode()
        {
            var result = _formatter.FormatPhoneNumber("1234567890");

            Assert.StartsWith(result, "(123)");
        }

        [TestMethod]
        public void FormatsValidDigits_EndsWithLastFourDigits()
        {
            var result = _formatter.FormatPhoneNumber("1234567890");

            Assert.EndsWith(result, "7890");
        }

        [TestMethod]
        public void FormatsValidDigits_ReturnsFullFormat()
        {
            var result = _formatter.FormatPhoneNumber("5551234567");

            Assert.AreEqual("(555) 123-4567", result);
        }

        [TestMethod]
        public void NullDigits_ThrowsArgumentNullException()
        {
            Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        }

        [TestMethod]
        [DataRow("123")]
        [DataRow("12345678901")]
        [DataRow("")]
        public void InvalidLength_ThrowsArgumentException(string digits)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
        }
    }

    [TestClass]
    public sealed class BuildGreetingTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void DefaultTitle_StartsWithDearMr()
        {
            var result = _formatter.BuildGreeting("Smith");

            Assert.StartsWith(result, "Dear Mr.");
        }

        [TestMethod]
        public void DefaultTitle_EndsWithNameAndComma()
        {
            var result = _formatter.BuildGreeting("Smith");

            Assert.EndsWith(result, "Smith,");
        }

        [TestMethod]
        public void CustomTitle_StartsWithDearAndTitle()
        {
            var result = _formatter.BuildGreeting("Johnson", "Dr.");

            Assert.StartsWith(result, "Dear Dr.");
        }

        [TestMethod]
        public void CustomTitle_ReturnsFullGreeting()
        {
            var result = _formatter.BuildGreeting("Johnson", "Dr.");

            Assert.AreEqual("Dear Dr. Johnson,", result);
        }

        [TestMethod]
        [DataRow(null)]
        [DataRow("")]
        [DataRow("   ")]
        public void NullOrWhitespaceName_Throws(string? name)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
        }
    }

    [TestClass]
    public sealed class GenerateSlugTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void SimpleTitle_ReturnsLowercaseSlug()
        {
            var result = _formatter.GenerateSlug("Hello World");

            Assert.AreEqual("hello-world", result);
        }

        [TestMethod]
        public void TitleWithSpecialChars_DoesNotStartWithHyphen()
        {
            var result = _formatter.GenerateSlug("  --Hello World--  ");

            Assert.StartsWith(result, "hello");
        }

        [TestMethod]
        public void TitleWithSpecialChars_DoesNotEndWithHyphen()
        {
            var result = _formatter.GenerateSlug("  --Hello World--  ");

            Assert.EndsWith(result, "world");
        }

        [TestMethod]
        [DataRow("My Blog Post!", "my-blog-post")]
        [DataRow("C# is GREAT", "c-is-great")]
        [DataRow("  spaces  everywhere  ", "spaces-everywhere")]
        public void VariousTitles_ProducesExpectedSlugs(string title, string expected)
        {
            var result = _formatter.GenerateSlug(title);

            Assert.AreEqual(expected, result);
        }

        [TestMethod]
        [DataRow(null)]
        [DataRow("")]
        [DataRow("   ")]
        public void NullOrWhitespaceTitle_Throws(string? title)
        {
            Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title!));
        }
    }

    [TestClass]
    public sealed class FormatCurrencyTests
    {
        private readonly StringFormatter _formatter = new();

        [TestMethod]
        public void DefaultSymbol_StartsWithDollarSign()
        {
            var result = _formatter.FormatCurrency(19.99m);

            Assert.StartsWith(result, "$");
        }

        [TestMethod]
        public void CustomSymbol_StartsWithSymbol()
        {
            var result = _formatter.FormatCurrency(19.99m, "€");

            Assert.StartsWith(result, "€");
        }

        [TestMethod]
        public void WholeNumber_EndsWithTwoDecimalPlaces()
        {
            var result = _formatter.FormatCurrency(100m);

            Assert.EndsWith(result, ".00");
        }

        [TestMethod]
        public void FormatsWithTwoDecimalPlaces()
        {
            var result = _formatter.FormatCurrency(9.5m, "£");

            Assert.AreEqual("£9.50", result);
        }

        [TestMethod]
        public void NegativeAmount_FormatsCorrectly()
        {
            var result = _formatter.FormatCurrency(-5.25m);

            Assert.AreEqual("$-5.25", result);
        }
    }
}

